.user-list-section {
  /* Bỏ background, border-radius, box-shadow vì đã có ở admin-page-container */
}

.user-list-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 1.5rem;
}

.user-list-header h2 {
  font-size: 1.2rem;
  font-weight: 600;
  color: #1a1c23;
  margin: 0;
}

.header-actions {
  display: flex;
  gap: 1rem;
}

.search-box {
  position: relative;
  width: 300px;
}

.search-box i {
  position: absolute;
  left: 12px;
  top: 50%;
  transform: translateY(-50%);
  color: #6b7280;
  font-size: 0.9rem;
}

.search-box input {
  width: 100%;
  padding: 0.5rem 0.75rem 0.5rem 2.25rem;
  border: 1px solid #e5e7eb;
  border-radius: 8px;
  font-size: 0.9rem;
  transition: all 0.3s ease;
}

.search-box input:focus {
  outline: none;
  border-color: #3b82f6;
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.1);
}

.user-table {
  width: 100%;
  border-collapse: separate;
  border-spacing: 0;
}

.user-table th,
.user-table td {
  padding: 1rem;
  vertical-align: middle;
  border-bottom: 1px solid #e5e7eb;
}

.user-table th {
  font-weight: 600;
  color: #4b5563;
  background: #f9fafb;
  text-align: left;
}

.user-table th:first-child {
  border-top-left-radius: 8px;
}

.user-table th:last-child {
  border-top-right-radius: 8px;
}

.user-info {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.user-info i {
  font-size: 1.25rem;
  color: #6b7280;
}

.role-select {
  padding: 0.375rem 2rem 0.375rem 0.75rem;
  border: 1px solid #e5e7eb;
  border-radius: 6px;
  font-size: 0.875rem;
  color: #1f2937;
  background-color: #fff;
  background-image: url("data:image/svg+xml,%3csvg xmlns='http://www.w3.org/2000/svg' fill='none' viewBox='0 0 20 20'%3e%3cpath stroke='%236B7280' stroke-linecap='round' stroke-linejoin='round' stroke-width='1.5' d='M6 8l4 4 4-4'/%3e%3c/svg%3e");
  background-position: right 0.5rem center;
  background-repeat: no-repeat;
  background-size: 1.5em 1.5em;
  appearance: none;
}

.role-select.admin {
  color: #2563eb;
  border-color: #93c5fd;
  background-color: #eff6ff;
}

.role-select:focus {
  outline: none;
  border-color: #3b82f6;
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.1);
}

.action-buttons {
  display: flex;
  gap: 0.5rem;
  justify-content: center;
}

.btn-delete {
  padding: 0.375rem;
  border: none;
  border-radius: 6px;
  background: #fee2e2;
  color: #dc2626;
  cursor: pointer;
  transition: all 0.2s ease;
}

.btn-delete:hover {
  background: #fecaca;
}

.btn-delete i {
  font-size: 1rem;
}

/* Responsive */
@media (max-width: 768px) {
  .user-list-header {
    flex-direction: column;
    gap: 1rem;
    align-items: stretch;
  }

  .search-box {
    width: 100%;
  }

  .user-table {
    display: block;
    overflow-x: auto;
    white-space: nowrap;
  }
}