  margin: 0 auto;
  padding: 5px;
  font-family: Arial, Helvetica, sans-serif;
}

html {
  scroll-behavior: smooth;
}

/* Breadcrumb */
.breadcrumb {
  font-size: 14px;
  color: #666;
  margin-bottom: 10px;
}

/* Main Content: Chia 2 cột */
.main-location-content {
  display: flex;
  gap: 30px;
}

/* Cột trái: Nội dung chính */
